const DIR = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const { fig, near, dist, mid, parallel, parallelogram, isMid, angDeg, perimeter, area, must, polar, meet, add, sub, triFromSides, midTheorem, midProof, converse, converseProof, medial, quadMid, trapezium, intercepts, divide } = G;
const d = (s) => `$${s}$`;

// ---------------------------------------------------------------- facts verified for the slides
// Mid-point theorem on the main triangle (A (3.6, 6.4), B (0, 0), C (8, 0)): DE = 4 = BC / 2.
must(near(F.M1.bc, 8) && near(F.M1.de, 4) && parallel(F.M1.D, F.M1.E, F.T1.B, F.T1.C), 'main triangle');
must(near(angDeg(F.M1.D, F.T1.A, F.M1.E), angDeg(F.T1.B, F.T1.A, F.T1.C)) && near(angDeg(F.M1.E, F.T1.A, F.M1.D), angDeg(F.T1.C, F.T1.A, F.T1.B)), 'corresponding angles');
const proofRows = (() => {
  const { D, E, F: Fp } = F.P1; const { A, B, C } = F.T1;
  must(near(dist(A, E), dist(E, C)) && near(dist(D, E), dist(E, Fp)) && near(angDeg(E, A, D), angDeg(E, C, Fp)), 'SAS match');
  must(near(dist(A, D), dist(C, Fp)) && near(dist(A, D), dist(D, B)), 'CF = AD = DB');
  must(parallelogram(B, D, Fp, C) && near(dist(D, Fp), dist(B, C)) && near(dist(D, E), dist(D, Fp) / 2), 'BDFC parallelogram; DE = DF / 2');
  return true;
})();
// Example 1 (part 1): ST = 6.5 so QR = 13.
const e1 = (() => { const t = { A: [4.2, 8], B: [0, 0], C: [13, 0] }; const m = midTheorem(t.A, t.B, t.C); must(near(m.de, 6.5) && near(m.bc, 13), 'e1'); return { t, m }; })();
// Example 2: DE = 2x + 1, BC = 5x - 7: x = 9, DE = 19, BC = 38.
const e2 = (() => { const x = 9; must(2 * (2 * x + 1) === 5 * x - 7 && 2 * x + 1 === 19 && 5 * x - 7 === 38, 'e2 algebra'); const t = { A: [14, 30], B: [0, 0], C: [38, 0] }; const m = midTheorem(t.A, t.B, t.C); must(near(m.de, 19) && near(m.bc, 38), 'e2 geometry'); return { t, m }; })();
// Example 3: angle B = 54, angle C = 71: ADE = 54, AED = 71, A = 55, DEC = 109.
const e3 = (() => {
  const B = [0, 0], C = [9.2, 0]; const A = meet(B, polar(B, 1, 54), C, polar(C, 1, 180 - 71)); const m = midTheorem(A, B, C);
  must(near(angDeg(B, A, C), 54) && near(angDeg(C, A, B), 71) && near(angDeg(A, B, C), 55), 'e3 angles');
  must(near(angDeg(m.D, A, m.E), 54) && near(angDeg(m.E, A, m.D), 71) && near(angDeg(m.E, m.D, C), 109), 'e3 derived angles');
  return { A, B, C, ...m };
})();
// Example 4: triangle sides 6.8, 9, 11.6; the triangle of mid-points has 3.4, 4.5, 5.8 (perimeter 13.7).
const e4 = (() => { const t = triFromSides(6.8, 9, 11.6); const m = medial(t.A, t.B, t.C); must(near(dist(m.D, m.E), 3.4) && near(dist(m.E, m.F), 4.5) && near(dist(m.F, m.D), 5.8) && near(m.per, 13.7) && near(m.perABC, 27.4), 'e4'); return { t, m }; })();
// Example 5: diagonals 16 and 10, perpendicular: rectangle 8 by 5, perimeter 26, area 40.
const e5 = (() => { const A = [0, 0], C = [16, 0], B = [6, -4], D = [6, 6]; const m = quadMid(A, B, C, D); must(m.perpendicularDiagonals && near(m.ac, 16) && near(m.bd, 10) && near(dist(m.P, m.Q), 8) && near(dist(m.Q, m.R), 5) && near(m.per, 26) && near(area(m.P, m.Q, m.R, m.S), 40), 'e5'); return { A, B, C, D, m }; })();
// Special cases of the quadrilateral of mid-points.
const special = (() => {
  const kinds = (A, B, C, D) => { const m = quadMid(A, B, C, D); const sides = [dist(m.P, m.Q), dist(m.Q, m.R), dist(m.R, m.S), dist(m.S, m.P)]; const rect = near(G.dot(sub(m.Q, m.P), sub(m.R, m.Q)), 0, 1e-9); const rh = sides.every((x) => near(x, sides[0])); return { m, rect, rh }; };
  const gen = kinds([0.5, 1.5], [6, 0], [9, 5], [2, 7.5]);
  const eq = kinds([0, 0], [9, 0], [9, 4], [0, 4]); // rectangle: equal diagonals, not perpendicular
  const pe = kinds([0, 0], [9, -6], [24, 0], [9, 12]); // kite: perpendicular, unequal
  const sq = kinds([0, 0], [4, -4], [8, 0], [4, 4]); // square: equal and perpendicular
  must(!gen.rect && !gen.rh && !gen.m.equalDiagonals && !gen.m.perpendicularDiagonals, 'generic');
  must(eq.m.equalDiagonals && !eq.m.perpendicularDiagonals && eq.rh && !eq.rect, 'equal diagonals: rhombus');
  must(pe.m.perpendicularDiagonals && !pe.m.equalDiagonals && pe.rect && !pe.rh, 'perpendicular diagonals: rectangle');
  must(sq.m.perpendicularDiagonals && sq.m.equalDiagonals && sq.rect && sq.rh, 'both: square');
  return true;
})();
// Deck 2 example 1: D mid-point of AB, DE parallel to BC, DE = 5.9, AC = 17.4: AE = EC = 8.7, BC = 11.8.
const c1 = (() => { const t = triFromSides(13, 11.8, 17.4); const c = converse(t.A, t.B, t.C); must(near(dist(c.D, c.E), 5.9) && near(dist(t.A, c.E), 8.7) && near(dist(c.E, t.C), 8.7) && near(dist(t.B, t.C), 11.8), 'c1'); return { t, c }; })();
// Example 2: AE = 2x + 5 = EC = 4x - 7: x = 6, AE = 17, AC = 34.
const c2 = (() => { const x = 6; must(2 * x + 5 === 4 * x - 7 && 2 * x + 5 === 17, 'c2 algebra'); const t = { A: [0, 0], C: [34, 0], B: [11, 18] }; const c = converse(t.A, t.B, t.C); must(near(dist(t.A, c.E), 17) && near(dist(c.E, t.C), 17), 'c2 geometry'); return { t, c }; })();
// Why the mid-point matters: D at ratio AD : DB = 1 : 1, 1 : 2, 1 : 3 gives E at AE : EC = 1 : 1, 1 : 2, 1 : 3.
const ratios = (() => {
  const t = { A: [6, 8], B: [0, 0], C: [15, 0] };
  return [1, 2, 3].map((k) => { const D = G.lerp(t.A, t.B, 1 / (k + 1)); const E = meet(D, add(D, sub(t.C, t.B)), t.A, t.C); must(parallel(D, E, t.B, t.C), 'parallel'); const rd = dist(t.A, D) / dist(D, t.B), re = dist(t.A, E) / dist(E, t.C); must(near(rd, 1 / k) && near(re, 1 / k), `ratio 1 : ${k}`); return { k, mid: k === 1 }; });
})();
// Example 3 (deck 2): P mid-point of XY, PQ parallel to YZ, QR parallel to XY. XY = 9.4, YZ = 12.6: PQ = 6.3, QR = 4.7, PYRQ perimeter 22.
const chain = (() => { const t = triFromSides(9.4, 12.6, 11); const c = converse(t.A, t.B, t.C); const R = meet(c.E, add(c.E, sub(t.B, t.A)), t.B, t.C); must(isMid(R, t.B, t.C) && parallelogram(c.D, t.B, R, c.E) && near(dist(c.D, c.E), 6.3) && near(dist(c.E, R), 4.7) && near(perimeter(c.D, t.B, R, c.E), 22), 'chain'); return true; })();
// Example 4 (deck 2): four rails, intercept 2.8 on the first bar; 11.4 on the second between first and fourth: 3.8 each, first to third 7.6.
const i4 = (() => { const s = intercepts([0, 0], [2.4, 7], [1, 0.35], [0, 1 / 3, 2 / 3, 1], [8, -0.5], [9.5, 6.5]); must(s.s2.length === 3 && s.s2.every((x) => near(x, s.s2[0])) && near(11.4 / 3, 3.8) && near(2 * 3.8, 7.6), 'i4'); return true; })();
// Example 5 (deck 2): trapezium bases 9.6 and 17.2: mid-line 13.4; segment between mid-points of diagonals 3.8.
